#pragma once
#include "Wire.h"
template<>struct Wire<FT_COMMAND>;
template<>struct Wire<FT_EVENT>;
template<>struct Wire<FT_HEADER>;
template<>struct Wire<FT_REPLY>;
template<>struct Wire<FT_COMMAND> {static Json Encode(const FT_COMMAND& v){Json j=Json::object();j["Version"]=EncodeWire(v.Version);j["Size"]=EncodeWire(v.Size);j["Operation"]=EncodeWire(v.Operation);j["ProcessId"]=EncodeWire(v.ProcessId);return j;}static void Decode(const Json& j,FT_COMMAND& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Version")DecodeWire(it.value(),v.Version);else if(it.key()=="Size")DecodeWire(it.value(),v.Size);else if(it.key()=="Operation")DecodeWire(it.value(),v.Operation);else if(it.key()=="ProcessId")DecodeWire(it.value(),v.ProcessId);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<FT_EVENT> {static Json Encode(const FT_EVENT& v){Json j=Json::object();j["Sequence"]=EncodeWire(v.Sequence);j["StartTicks"]=EncodeWire(v.StartTicks);j["DurationTicks"]=EncodeWire(v.DurationTicks);j["RequestedBytes"]=EncodeWire(v.RequestedBytes);j["TransferredBytes"]=EncodeWire(v.TransferredBytes);j["ProcessId"]=EncodeWire(v.ProcessId);j["Status"]=EncodeWire(v.Status);j["Operation"]=EncodeWire(v.Operation);j["Flags"]=EncodeWire(v.Flags);j["Reserved"]=EncodeWire(v.Reserved);return j;}static void Decode(const Json& j,FT_EVENT& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Sequence")DecodeWire(it.value(),v.Sequence);else if(it.key()=="StartTicks")DecodeWire(it.value(),v.StartTicks);else if(it.key()=="DurationTicks")DecodeWire(it.value(),v.DurationTicks);else if(it.key()=="RequestedBytes")DecodeWire(it.value(),v.RequestedBytes);else if(it.key()=="TransferredBytes")DecodeWire(it.value(),v.TransferredBytes);else if(it.key()=="ProcessId")DecodeWire(it.value(),v.ProcessId);else if(it.key()=="Status")DecodeWire(it.value(),v.Status);else if(it.key()=="Operation")DecodeWire(it.value(),v.Operation);else if(it.key()=="Flags")DecodeWire(it.value(),v.Flags);else if(it.key()=="Reserved")DecodeWire(it.value(),v.Reserved);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<FT_HEADER> {static Json Encode(const FT_HEADER& v){Json j=Json::object();j["Version"]=EncodeWire(v.Version);j["Size"]=EncodeWire(v.Size);j["Count"]=EncodeWire(v.Count);j["Capacity"]=EncodeWire(v.Capacity);j["ActiveProcessId"]=EncodeWire(v.ActiveProcessId);j["Inflight"]=EncodeWire(v.Inflight);j["Dropped"]=EncodeWire(v.Dropped);j["Frequency"]=EncodeWire(v.Frequency);j["Epoch"]=EncodeWire(v.Epoch);j["NextSequence"]=EncodeWire(v.NextSequence);return j;}static void Decode(const Json& j,FT_HEADER& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Version")DecodeWire(it.value(),v.Version);else if(it.key()=="Size")DecodeWire(it.value(),v.Size);else if(it.key()=="Count")DecodeWire(it.value(),v.Count);else if(it.key()=="Capacity")DecodeWire(it.value(),v.Capacity);else if(it.key()=="ActiveProcessId")DecodeWire(it.value(),v.ActiveProcessId);else if(it.key()=="Inflight")DecodeWire(it.value(),v.Inflight);else if(it.key()=="Dropped")DecodeWire(it.value(),v.Dropped);else if(it.key()=="Frequency")DecodeWire(it.value(),v.Frequency);else if(it.key()=="Epoch")DecodeWire(it.value(),v.Epoch);else if(it.key()=="NextSequence")DecodeWire(it.value(),v.NextSequence);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<FT_REPLY> {static Json Encode(const FT_REPLY& v){Json j=Json::object();j["Header"]=EncodeWire(v.Header);j["Events"]=EncodeWire(v.Events);return j;}static void Decode(const Json& j,FT_REPLY& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Header")DecodeWire(it.value(),v.Header);else if(it.key()=="Events")DecodeWire(it.value(),v.Events);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
